import { useEffect, useState } from 'react';
import axios from '../api/axios';

export default function AdminPage() {
  const [mode, setMode] = useState('clients');

  const [clients, setClients] = useState([]);
  const [form, setForm] = useState({
    fullName: '',
    email: '',
    phone: '',
    notes: '',
    role: 'client',
    password: ''
  });
  const [editingClient, setEditingClient] = useState(null);

  // загрузка списка
  useEffect(() => {
    axios.get('/clients')
      .then(res => setClients(res.data))
      .catch(err => console.error(err));
  }, []);

  // добавление клиента
  const handleCreate = async (e) => {
    e.preventDefault();
    try {
      const payload = { ...form };
      const res = await axios.post('/clients', payload);
      setClients([...clients, res.data]);
      setForm({ fullName: '', email: '', phone: '', notes: '', role: 'client', password: '' });
    } catch (err) {
      alert(err.response?.data?.error || 'Ошибка создания');
    }
  };

  // удаление клиента
  const handleDelete = async (id) => {
    try {
      await axios.delete(`/clients/${id}`);
      setClients(clients.filter(c => c._id !== id));
    } catch (err) {
      alert('Ошибка удаления');
    }
  };

  // открыть форму редактирования
  const handleEditClick = (client) => {
    setEditingClient({ ...client });
  };

  // изменение полей формы редактирования
  const handleEditChange = (e) => {
    const { name, value } = e.target;
    setEditingClient({ ...editingClient, [name]: value });
  };

  // сохранить изменения
  const handleEditSubmit = async (e) => {
    e.preventDefault();
    try {
      const res = await axios.put(`/clients/${editingClient._id}`, editingClient);
      setClients(clients.map(c => c._id === editingClient._id ? res.data : c));
      setEditingClient(null);
    } catch (err) {
      alert('Ошибка обновления');
    }
  };

  return (
    <main className="container section fade-in">
      <article className="card">
        <h2 className="h2">Админ‑панель</h2>

        {/* форма добавления */}
        <form className="form" onSubmit={handleCreate}>
          <div className="form__row form__row--two">
            <input
              className="form__input"
              placeholder="ФИО"
              value={form.fullName}
              onChange={e => setForm({ ...form, fullName: e.target.value })}
              required
            />
            <input
              className="form__input"
              placeholder="Email"
              type="email"
              value={form.email}
              onChange={e => setForm({ ...form, email: e.target.value })}
              required
            />
          </div>
          <div className="form__row form__row--two">
            <input
              className="form__input"
              placeholder="Телефон"
              value={form.phone}
              onChange={e => setForm({ ...form, phone: e.target.value })}
              required
            />
            <input
              className="form__input"
              placeholder="Пароль"
              type="password"
              value={form.password}
              onChange={e => setForm({ ...form, password: e.target.value })}
              required
            />
          </div>
          <textarea
            className="form__input"
            placeholder="Заметки"
            value={form.notes}
            onChange={e => setForm({ ...form, notes: e.target.value })}
          />
          <select
            className="form__input"
            value={form.role}
            onChange={e => setForm({ ...form, role: e.target.value })}
          >
            <option value="client">Клиент</option>
            <option value="admin">Админ</option>
          </select>
          <div className="form__actions">
            <button className="btn btn--success" type="submit">Добавить клиента</button>
          </div>
        </form>

        {/* список клиентов */}
        <ul className="info-list">
          {clients.map(c => (
            <li key={c._id} className="info-list__item">
              <div>
                <strong>{c.fullName}</strong> <span className="muted">({c.role})</span><br />
                <span className="info-list__label">Email:</span> {c.email}<br />
                <span className="info-list__label">Телефон:</span> {c.phone}<br />
                <span className="info-list__label">Заметки:</span> {c.notes || '—'}<br />
                <span className="info-list__label">Создан:</span> {new Date(c.createdAt).toLocaleString()}<br />
                <span className="info-list__label">Обновлён:</span> {new Date(c.updatedAt).toLocaleString()}
              </div>
              <div className="form__actions">
                <button className="btn btn--ghost" onClick={() => handleEditClick(c)}>Редактировать</button>
                <button className="btn btn--danger" onClick={() => handleDelete(c._id)}>Удалить</button>
              </div>
            </li>
          ))}
        </ul>

        {/* форма редактирования */}
        {editingClient && (
          <form className="form" onSubmit={handleEditSubmit}>
            <h3 className="h2">Редактирование клиента</h3>
            <input
              className="form__input"
              name="fullName"
              value={editingClient.fullName}
              onChange={handleEditChange}
              placeholder="ФИО"
              required
            />
            <input
              className="form__input"
              name="email"
              type="email"
              value={editingClient.email}
              onChange={handleEditChange}
              placeholder="Email"
              required
            />
            <input
              className="form__input"
              name="phone"
              value={editingClient.phone}
              onChange={handleEditChange}
              placeholder="Телефон"
              required
            />
            <textarea
              className="form__input"
              name="notes"
              value={editingClient.notes || ''}
              onChange={handleEditChange}
              placeholder="Заметки"
            />
            <select
              className="form__input"
              name="role"
              value={editingClient.role}
              onChange={handleEditChange}
            >
              <option value="client">Клиент</option>
              <option value="admin">Админ</option>
            </select>
            <div className="form__actions">
              <button className="btn btn--success" type="submit">Сохранить</button>
              <button className="btn btn--ghost" type="button" onClick={() => setEditingClient(null)}>Отмена</button>
            </div>
          </form>
        )}
      </article>
    </main>
  );
}
